function nightRoute(p,route){
 return womenNightRoutes[p]?.[route]||menNightRoutes[p]?.[route];
}
function loveNightScene(p,count,route){
 const selected=nightRoute(p,route);
 if(selected)return selected;
 return count>1&&count%2===0?familiarNightScenes[p]:longNightScenes[p];
}
function renderNightPassage(p,story,part){
 add('이야기',story[part]);
 const reaction=story.reaction;
 if(reaction.at!==part)return;
 const player=reaction.speaker==='player';
 add(player?state.name:p,reaction.line,player);
 add('이야기',reaction.next);
}
