function chapterLetter(p,day){
 const v=initSim(),r=v.couple?.[p],last=r?.chapters?.[2];
 if(!vIsDating(p)||!last||r.chapterLetterDay||day-r.since<200||day<=last.day||touchContext(p,day).conflicted||relationshipBoundaryLine(p,day))return null;
 const note=coupleChapterLetters[p],npc=speechRegisterIndex(p,'npc',day),player=speechRegisterIndex(p,'player',day);
 const script=[note.opening[last.choice][npc],''];
 for(const opt of note.choices)script.push(opt.say[player],opt.reply[npc]);
 return {chapterLetter:true,contextKey:'couple:letter:'+r.since,script};
}
function chapterLetterScript(p,m,day){
 if(!m.chapterLetter||m.reply)return m.script;
 const npc=speechRegisterIndex(p,'npc',day),player=speechRegisterIndex(p,'player',day);
 const script=m.script.slice(0,2);
 for(const opt of coupleChapterLetters[p].choices)script.push(opt.say[player],opt.reply[npc]);
 return script;
}
