function alleyKissReady(p,day){
 if(!vIsDating(p)||relationshipBoundaryLine(p,day))return false;
 const mood=touchContext(p,day);
 return !mood.tired&&!mood.conflicted;
}
function canWalkHome(ev,p){
 const v=initSim(),run=v.running;
 if(!ev.dateEvent||v.activeEvent!==ev||!run||v.day!==ev.day||!alleyKissReady(p,ev.day))return false;
 const slot=ev.slot??run.slot;
 if(slot!==run.slot||slot<1||slot>3)return false;
 for(let i=slot+1;i<=3;i++){
  if(run.plan[i]!=='휴식'||fixedActivity(ev.day,i)||!npcMeetingTime(p,ev.day,i))return false;
 }
 return true;
}
function offerAlleyWalk(ev,p,choices){
 if(!canWalkHome(ev,p))return;
 const casual=speechRegisterIndex(p,'player',ev.day),slot=ev.slot??initSim().running.slot;
 const label=slot===3?(casual?'집 앞까지 같이 걸을래?':'집 앞까지 같이 걸을래요?'):
  (casual?'저녁까지 같이 있다가 집 앞까지 걸을래?':'저녁까지 같이 있다가 집 앞까지 걸을래요?');
 choices.push([label,alleyDateVoices[p].walk[speechRegisterIndex(p,'npc',ev.day)],2,'alley']);
}
function renderAlleyDate(ev,p){
 const v=initSim(),o=ev.alleyDate,day=ev.day,lines=alleyDateVoices[p];
 const live=()=>v.activeEvent===ev&&ev.alleyDate===o&&v.day===day;
 const refresh=()=>{save();renderChoiceEvent();renderSim()};
 const finish=()=>{if(live())finishEvent()};
 if(!o.walking){
  // A public encounter may have changed how the date feels after the walk was offered.
  if(!canWalkHome(ev,p)){
   add('이야기','조금 더 걸으려다 큰길에서 인사를 나눴다. 오늘은 각자 돌아가기로 했다.');
   choiceButton('일정 계속하기',finish);return;
  }
  o.walking=true;
  v.running.slot=v.slot=3;
  if(o.fromSlot<3)v.running.notes.push(nameWith(p)+' 저녁까지 데이트를 이어 갔다.');
  save();
 }
 const pc=speechRegisterIndex(p,'player',day),npc=speechRegisterIndex(p,'npc',day);
 const near='눈을 맞추고 입을 맞춘다';
 const gentle=pc?'오늘은 손만 잡고 걸을래.':'오늘은 손만 잡고 걸을래요.';
 const part=pc?'오늘은 여기서 인사할까?':'오늘은 여기서 인사할까요?';
 const homeLine=pc?'우리 집으로 갈래?':'우리 집으로 갈래요?';
 const home=addressTurn(p,day)%4===3?spokenCall(p,'player',day,homeLine):homeLine;
 $('where').textContent='연화동 골목길';$('progress').textContent='데이트 · 집에 가는 길';
 $('clock').textContent='DAY '+day+' · 저녁 · '+weatherFor(day).icon+' '+weatherFor(day).name;
 if(o.fromSlot<3)add('이야기','저녁을 같이 먹고 나왔을 때는 간판마다 불이 켜져 있었다. 둘이 나란히 동네 쪽으로 걸었다.');
 add('이야기','큰길을 벗어나자 차 소리가 잦아들었다. 골목 안쪽은 어두웠고, 한참 뒤에야 담장 위로 가로등 불빛이 비쳤다.');
 add('이야기',lines.arrival);
 add(p,lines.invite[npc]);
 if(!o.kiss){
  choiceButton(near,()=>{
   if(!live()||o.kiss)return;
   o.kiss='yes';
   flirtRecord(p).touches.push({day,type:'입맞춤',scene:'골목길'});
   remember(p,'date:alleyKiss:'+day,'집에 가는 길, 어두운 골목에서 입을 맞췄다.');
   refresh();
  });
  choiceButton(gentle,()=>{if(live()&&!o.kiss){o.kiss='no';refresh()}});
  return;
 }
 if(o.kiss==='no'){
  add(state.name,gentle,true);
  add('이야기','우리는 손을 잡고 다시 큰길로 나왔다. 갈림길에 닿아서야 맞잡은 손을 놓았다.');
  add(p,lines.part[npc]);choiceButton('일정 계속하기',finish);return;
 }
 add('이야기',lines.kiss);
 const canStay=()=>live()&&overnightReady(p,day,true);
 if(!o.destination){
  if(canStay())choiceButton(home,()=>{
   if(!live()||o.destination)return;
   if(!canStay()){refresh();return}
   o.destination='home';o.night={kiss:'confirmed'};refresh();
  });
  choiceButton(part,()=>{if(live()&&!o.destination){o.destination='part';refresh()}});
  return;
 }
 if(o.destination==='part'){
  add(state.name,part,true);add(p,lines.part[npc]);choiceButton('일정 계속하기',finish);return;
 }
 add(state.name,home,true);add(p,lines.home[npc]);
 $('where').textContent='우리 집';$('progress').textContent='데이트 · 집에 돌아와서';
 add('이야기','현관에 나란히 신발을 벗어 두었다. 물 두 잔을 들고 돌아오니 소파 한쪽이 나를 위해 비어 있었다. 잔을 내려놓고 그 옆에 앉았다.');
 if((ev.pairItemQuestion||!o.night.approach&&!o.night.ending&&!o.night.invitation)&&renderPairItemQuestion(ev,p))return;
 renderIntimateEvening(ev,p,o.night,{
  host:'player',canStay,onStay:()=>recordOvernightStay(p,day),onFinish:finish,refresh
 });
}

function renderWorkshopCup(ev){
 const cup=ev.workshopCup,beat=approvedDailyTalks['차유리']['05'];
 add('이야기','유리가 공방 진열대에 놓인 컵 하나를 집어 들었다.');
 add(ev.person,dailySpeech(ev,'npc',beat.opening),false,false,'기본',true);
 const selected=beat.choices.find(choice=>choice.label===cup.answer);
 if(selected){
  renderApprovedAnswer(ev,selected,dailySpeech(ev,'player',selected.label));
  return false;
 }
 for(const choice of beat.choices){
  choiceButton(dailySpeech(ev,'player',choice.label),()=>{
   const v=initSim();
   if(v.activeEvent!==ev||cup.answer||ev.answered)return;
   cup.answer=choice.label;
   v.affection[ev.person]=Math.min(999,(v.affection[ev.person]||0)+2);
   save();renderChoiceEvent();renderSim();
  });
 }
 return true;
}
