function pairItemLabel(kind){return kind==='ring'?'커플링':'커플 팔찌'}
function pairItemDesign(p,kind){return pairItemDesigns[p][kind==='ring'?0:1]}
function pairItemState(){
 const v=initSim();
 return v.pairItems||(v.pairItems={owned:[],worn:null,offers:{},notices:{}});
}
function pairItemFor(p){
 if(!vIsDating(p))return null;
 const since=coupleRecord(p).since;
 return pairItemState().owned.find(item=>item.person===p&&item.since===since)||null;
}
function wornPairItem(){
 const items=pairItemState();
 return items.owned.find(item=>item.id===items.worn)||null;
}
function setWornPairItem(id){
 const items=pairItemState();
 if(id!==null&&!items.owned.some(item=>item.id===id))return false;
 items.worn=id;return true;
}
function givePairItem(p,kind,wear=false){
 if(!people.includes(p)||!vIsDating(p)||!['ring','bracelet'].includes(kind))return null;
 let item=pairItemFor(p);
 if(!item){
  const since=coupleRecord(p).since;
  item={id:p+'|'+since,person:p,kind,since,day:initSim().day};
  pairItemState().owned.push(item);
 }
 if(wear)setWornPairItem(item.id);
 return item;
}
function renderPairItemsPanel(){
 const root=$('pairItemsPanel'),v=initSim(),items=v.pairItems?.owned||[];
 root.hidden=!items.length&&!lovers().length;
 if(root.hidden)return;
 const list=$('pairItemsList');list.replaceChildren();
 const hint=$('pairItemsHint'),ev=v.activeEvent;
 if(!items.length){hint.textContent='연인과 데이트를 하다 보면 둘이 함께 찰 물건을 고를 수 있어요.';return}
 const onDate=!!(ev?.dateEvent||ev?.alleyDate||ev?.sharedLife?.kind==='home');
 hint.textContent=v.finished?'올해 함께 맞춘 커플 아이템이에요.':onDate?'데이트가 끝나면 착용할 아이템을 바꿀 수 있어요.':'오늘 착용할 아이템을 하나 고를 수 있어요.';
 for(const item of items){
  const worn=v.pairItems.worn===item.id,p=item.person;
  const row=document.createElement('div');row.className='pair-item-row';row.dataset.owner=p;
  const copy=document.createElement('div'),title=document.createElement('b'),detail=document.createElement('small');
  title.textContent=p+' · '+pairItemLabel(item.kind)+(worn?' · 착용 중':'');
  detail.textContent=pairItemDesign(p,item.kind)+' · '+calendarDate(item.day).label+(pairItemFor(p)?.id===item.id?'':' · 지난 연애의 기념품');
  copy.append(title,detail);row.append(copy);
  const button=document.createElement('button');button.type='button';button.className='secondary';
  button.textContent=worn?'빼서 보관하기':'착용하기';button.disabled=onDate||!!v.finished;
  button.onclick=()=>{setWornPairItem(worn?null:item.id);save();renderPairItemsPanel()};
  row.append(button);list.append(row);
 }
}
function showMatchingOnDate(ev){
 const p=ev.person,day=ev.day??initSim().day;
 const opening=!ev.answered&&!ev.dateSteps?.length&&!ev.coupleChapter&&!ev.pairItemQuestion;
 if(!opening)return;
 if(!ev.wearingPairLine){
  const item=wornPairItem();
  if(!item||item.person!==p||item.day>=day||item.acknowledged||pairItemFor(p)?.id!==item.id||unresolvedOutingConflict(p)||coupleIssueRecord(p).active)return;
  ev.wearingPairLine=item.kind==='ring'?'손을 잡다가 반지끼리 살짝 부딪혔다. 둘이 동시에 손을 내려다보고 웃었다.':'손을 흔들며 다가오던 연인이 소매를 걷어 올렸다. 나도 손목을 들자 똑같은 팔찌 두 개가 나란히 보였다.';
  item.acknowledged=day;save();
 }
 add('이야기',ev.wearingPairLine);
}

