const souvenirReactions={"서이준":["…아직 가지고 있었네요. 다음에 또 가요.","…다른 분이랑 맞춘 거예요? 그냥 궁금해서요."],"강도윤":["그날 생각나네요. 아직 간직하고 계셨구나.","아, 저도 다음에는 기억에 남을 걸 골라 드려야겠네요. 하하."],"한시우":["와, 아직 있어요? 다음에 기록 깨러 가죠!","뭐야, 다른 사람이랑도 재밌게 놀았네요? 다음엔 저도 데려가요."],"백지한":["아직 가지고 계시네요. 기분 좋은데요.","어라, 다른 분과의 기념품이에요? 저랑도 하나 맞추고 싶은데."],"임하나":["아직 가지고 계셨구나. ……저도 잘 간직하고 있어요.","예쁘네요. ……저도 다음에 같이 고르고 싶어요."],"차유리":["오, 아직 갖고 있네요! 다음엔 다른 것도 만들어 봐요.","오, 예쁘다. 다음엔 저랑도 하나 골라요."],"오세린":["그날 참 편안했죠. 기억해 주셔서 좋아요.","좋은 추억인가 봐요. 저와도 많이 만들면 좋겠네요."],"정태오":["잘 보관하고 계셨군요. 저도 그날을 기억합니다.","다른 분과의 기념품입니까? 아, 그저 궁금했습니다."],"유지안":["헐 아직 있어요? 그날 진짜 재밌었는데!","와, 재밌었겠다! 다음엔 저랑도 신나게 놀아요."],"공재희":["헐 아직 갖고 다녀요? 기분 개좋아 ㅋㅋ","엥, 다른 사람이랑 맞춘 거예요? ……나랑도 맞추면 안 돼요?"]};
const souvenirChoiceReplies={"서이준":["…다음엔 제가 고를게요.","그날이 좋았다면 간직할 만하죠.","네. 제가 참견할 일은 아니죠.","…알겠어요. 다른 얘기 해요.","저도 가끔 그날 생각나요.","그럼 다음엔 좀 특이한 걸 찾아봐요."],"강도윤":["이번에는 오래 기억할 만한 걸 찾아볼게요.","좋은 기억이 있다는 건 좋은 일이죠.","제가 조금 욕심을 냈네요.","하하, 차라도 한 잔 할까요?","그 말을 들으니 선물한 보람이 있네요.","그럼 작은 기념품 가게도 찾아봐야겠네요."],"한시우":["오케이! 이번엔 제가 멋진 거 골라 볼게요.","오, 그렇게 소중한 거였구나.","맞죠. 제가 뭐라고 정하겠어요.","앗, 화제 전환! 뭐 얘기할까요?","와, 나도 그날 생각하면 웃겨요.","수집 취미였어요? 다음에 같이 찾아봐요."],"백지한":["좋아요. 볼 때마다 제 생각 나는 걸로요.","그렇군요. 저도 그런 추억을 만들고 싶네요.","맞는 말이에요. 제가 좀 신경 쓰였나 봐요.","…좋아요. 굳이 더 묻지는 않을게요.","그날이 저한테만 특별했던 건 아니네요.","그럼 다음에는 제가 하나 골라 드리죠."],"임하나":["정말요? 저도 예쁜 걸 찾아볼게요.","아…… 그만큼 좋은 날이었군요.","네. 제가 괜한 말을 했어요.","네! 다른 이야기 해요.","저도 그날 사진을 자주 봐요.","그럼 작은 것부터 하나씩 모아요."],"차유리":["좋다. 다음엔 직접 만들어 볼까요?","추억이 담긴 물건은 버리기 어렵죠.","당연하죠. 그냥 궁금해서 물었어요.","오케이. 다른 얘기 하죠.","오, 아직도 좋게 기억한다니 기분 좋네요.","수집하는 재미가 있죠. 예쁜 거 보면 알려 줄게요."],"오세린":["어머, 좋네요. 천천히 골라 봐요.","아아, 물건마다 사연이 있겠군요.","네. 각자의 추억은 존중해야죠.","으음, 그럼 요즘 어떻게 지내셨어요?","그날의 편안함이 저도 기억나요.","작은 물건들이 모이면 이야기가 되겠네요."],"정태오":["다음 외출 때 기념품 가게를 찾아보겠습니다.","소중히 보관하시는 이유가 있었군요.","옳은 말씀입니다. 실례했습니다.","알겠습니다. 다른 주제로 넘어가지요.","저 역시 좋은 기억으로 남아 있습니다.","수집하시는군요. 다음에 참고하겠습니다."],"유지안":["와, 좋아요! 엄청 귀여운 걸로 골라요!","아, 그럼 볼 때마다 기분 좋겠다!","앗, 맞아요! 제가 괜히 물었네.","오케이! 요즘 재밌는 일 없어요?","헐, 나도 그날 생각하면 신나요!","와, 모아 놓은 거 나중에 보여 줘요!"],"공재희":["헐 진짜? 그럼 커플템 같은 거 골라요 ㅋㅋ","아… 그렇게 좋았어요? 글쿠나.","웅. 맞는데… 걍 좀 신경 쓰였음.","아 ㅇㅋ. 딴 얘기 해요.","헐 나도! 아직 책상에 올려 놨어요 ㅋㅋ","오 수집러였음? 담에 귀여운 거 찾아봐요."]};
function renderSouvenirReaction(ev,p,mode='outing'){const v=initSim(),m=memoryFor(p),seen=m.souvenirSeen||(m.souvenirSeen={});if(!ev.souvenirReaction){const visible=souvenirList().filter(x=>!x.disposed&&x.day<v.day&&(mode==='home'?x.display==='방에 전시':x.display==='가방에 달기')&&!seen[x.person+'|'+x.venue]);const own=visible.find(x=>x.person===p),other=flirtRecord(p).interest>=6&&visible.find(x=>x.person!==p&&npcProfiles[x.person]?.gender===npcProfiles[p]?.gender);const x=own||other;if(!x)return false;ev.souvenirReaction={key:x.person+'|'+x.venue,name:x.name,other:x.person!==p};save()}const o=ev.souvenirReaction;add('이야기',p+'의 시선이 '+o.name+'에 머물렀다.');add(p,souvenirReactions[p][o.other?1:0]);if(o.answer){add(state.name,o.answer.label,true);add(p,o.answer.reply);return false}const opts=o.other?[['다음엔 우리도 기념품을 골라요.',souvenirChoiceReplies[p][0],{security:2,jealousy:-2}],['소중한 추억이라 간직하는 거예요.',souvenirChoiceReplies[p][1],{awareness:2}],['누구와 무엇을 간직할지는 제 자유예요.',souvenirChoiceReplies[p][2],{awareness:2}],['다른 이야기로 넘어간다',souvenirChoiceReplies[p][3],{}]]:[['그날이 좋아서 간직하고 있어요.',souvenirChoiceReplies[p][4],{security:2}],['기념품 모으는 걸 좋아해요.',souvenirChoiceReplies[p][5],{}]];for(const [label,reply,effect] of opts)choiceButton(label,()=>{if(o.answer)return;o.answer={label,reply};seen[o.key]=v.day;if(o.other)feel(p,{jealousy:2});feel(p,effect);save();renderChoiceEvent();renderSim()});return true}

function souvenirPanel(root){const h=document.createElement('h2');h.textContent='추억 상자 · 데이트 기념품';root.append(h);const items=souvenirList().filter(x=>!x.disposed);if(!items.length){const t=document.createElement('small');t.textContent='함께 보낸 날의 기념품이 이곳에 모입니다.';root.append(t)}for(const x of items){const d=document.createElement('details'),s=document.createElement('summary');s.textContent=x.name+' · '+x.person+' · '+calendarDate(x.day).label;d.append(s);const sel=document.createElement('select');const modes=['추억 상자에 보관','방에 전시'];if(/키링|열쇠고리|배지/.test(x.name))modes.push('가방에 달기');if(/사진|포토티켓/.test(x.name))modes.push('휴대전화 배경화면');for(const mode of modes){const opt=document.createElement('option');opt.value=mode;opt.textContent=mode;sel.append(opt)}if(x.exMarked)modes.push('따로 보관');if(x.exMarked){for(const mode of ['따로 보관']){const opt=document.createElement('option');opt.value=mode;opt.textContent=mode;sel.append(opt)}const b=document.createElement('button');b.className='secondary';b.textContent='기념품 정리하기';b.onclick=()=>{if(!confirm(x.name+'을(를) 정리할까요?'))return;x.disposed=true;x.display='정리함';save();renderSim()};d.append(b)}sel.value=x.display||modes[0];sel.onchange=()=>{x.display=sel.value;save()};d.append(sel);const t=document.createElement('p');t.textContent=x.venue+' — '+chatSpacing(x.line);d.append(t);for(const q of x.choices||[]){const p=document.createElement('p');p.textContent=chatSpacing(q.label+' / '+q.reply);d.append(p)}root.append(d)}}

function recordDate(ev,venue){const v=initSim(),p=ev.person,s=socialRecord(p),h=dateHistory(p);if(!h.some(x=>x.day===v.day))h.push({day:v.day,venue,highlight:dateMemoryLabel(ev),choices:(ev.dateSteps||[]).map(x=>x.label)});if(!ev.flirtRecorded){ev.flirtRecorded=true;flirtRecord(p).dates++;}s.lastTogether=v.day;s.lastDate={day:v.day,disclosed:!!ev.dateDisclosed};writeJournal(p+' · '+venue+' 외출 완료');if(platonicOnly(p))return;for(const q of people){if(q===p||aftermathRecord(q)||vIsDating(q)||friendshipRecord(q).bond||!socialRecord(q).contact||socialRecord(q).interest<4||v.affection[q]<45)continue;const z=socialRecord(q);if(z.lastJealous&&v.day-z.lastJealous<10)continue;const place=publicDatePlaces[venue]||({'시장 구경':'store','고양이 산책':'home','사진 산책':'park'}[venue]);const present=place?trianglePresent(place,v.day,v.slot):[];const witness=present.find(w=>w!==q&&w!==p&&triangleTies[q]?.includes(w));const source=present.includes(q)?'seen':witness?'heard':null;if(!source)continue;z.lastJealous=v.day;z.jealousPending={person:p,day:v.day,source,witness};z.jealousKnown={...z.jealousPending};feel(q,{jealousy:2});}}

const npcAutonomyVoices={"서이준":["서점","…이번에는 제가 가고 싶은 곳이 있는데, 같이 갈래요?","그날은 좀 쉬어야 할 것 같아요. 다른 날은 어때요?","…그럼 그날 봐요. 책 하나 추천해 드릴게요.","괜찮아요. 각자 할 일도 있으니까.","오늘은 집에 들어가서 쉬고 싶네요. 다음에 강변 같이 가요."],"강도윤":["시장 구경","하하, 저도 이번엔 손님으로 놀러 가고 싶어요. 같이 시장에 갈까요?","그날은 가게 일도 있고 조금 쉬어야겠어요. 다른 날로 맞춰 볼까요?","좋아요! 이번에는 제가 먹고 싶은 것도 골라 볼게요.","하하, 그럼 다음에 둘 다 여유 있을 때 만나요.","오늘은 마감하고 모카 챙겨야 해서요. 다음에 함께 걸어요."],"한시우":["보드게임 카페","오예, 새로운 보드게임 발견! 저랑 같이 해 볼래요?","앗, 그날은 연습하거나 손목 쉬어야 될 듯! 다른 날로 잡죠.","콜! 그날은 게임 설명부터 같이 읽어요.","오케이! 다음 기회에 같이 플레이해요.","앗 오늘은 연습이나 휴식 퀘스트 남았어요! 다음에 가요."],"백지한":["건축 산책","전에 말한 건물 기억나요? 이번엔 제가 코스 골라 보고 싶은데요.","그날은 제 일정도 챙겨야겠네요. 가능한 날을 다시 골라 볼까요?","좋죠. 이번에는 제가 길 안내할게요.","아쉽지만 그쪽 일정도 중요하죠. 다음 기회를 봅시다.","오늘은 제 일정이 남아 있어서 어렵겠어요. 다음엔 먼저 연락할게요."],"정태오":["수영장","휴무에 수영을 하려고 합니다. 함께하시겠습니까?","해당 날짜에는 개인 일정이 있습니다. 다른 휴무일은 어떠십니까?","알겠습니다. 약속 시간에 맞춰 가겠습니다.","무리하실 필요 없습니다. 다음에 시간을 조율하시죠.","오늘 저녁에는 시간을 내기 어렵습니다. 다음 휴무에 함께 걸으시죠."],"임하나":["서점","저… 이번에는 제가 가고 싶은 서점이 있어요. 같이 가 주실래요?","그날은 아르바이트나 제 일을 챙겨야 해요. 다른 날이면 좋겠어요.","……네! 이번엔 제가 보고 싶은 책부터 찾아볼래요.","네. 저도 다른 날 제 할 일을 하면서 기다릴게요.","저… 오늘은 제 시간이 조금 필요해요. 다음에 같이 가고 싶어요."],"차유리":["소품 공방","오, 재밌어 보이는 공방 발견했어요. 같이 뭔가 만들어 볼래요?","그날은 작업 시간을 비워 두려고요. 마감 뒤에 만나면 어때요?","좋다! 각자 만들고 싶은 거 생각해 와요.","오케이. 각자 할 일 하고 또 날짜 맞춰요!","오늘은 작업하려고 비워 둔 시간이거든요. 다음에 놀아요."],"오세린":["식물원","으음, 식물원에 계절 꽃이 피었다고 하네요. 함께 구경할까요?","그날은 쉬는 시간을 조금 갖고 싶어요. 다른 날 천천히 만나면 좋겠네요.","아아, 그날은 서두르지 않고 둘러봐요.","네. 서로 무리하지 않는 게 좋죠.","오늘은 병원 일도 있고 일찍 쉬려고요. 다음에 바람 쐬어요."],"유지안":["노래방","와우! 오늘 연습하다 노래방 가고 싶어졌어요. 날짜 잡을까요?","앗, 그날은 수업이나 회복 데이예요! 다른 날 신나게 놀죠.","예쓰! 부르고 싶은 노래 리스트 만들어 올게요.","넵! 각자 스케줄 맞을 때 다시 놀아요!","앗 오늘은 수업하거나 체력 회복해야 해요! 다음에 산책 콜?"],"공재희":["영화관","헐 보고 싶은 영화 개봉함ㅋㅋ 이번엔 나랑 같이 보러 가요.","아 그날은 방송이나 내 일정 있어서 좀 어려움… 다른 날 어때요?","웅ㅋㅋ 그날은 영화 끝나고 후기 얘기해요.","웅. 아쉽긴 한데 각자 할 일 하고 다시 잡아요.","아 오늘은 방송 준비하거나 좀 쉬어야 됨ㅋㅋ 다음에 강변 가요."]};
function npcDateFree(p,day){return dateSlot(p,day)!==null&&![299,300,365].includes(day)&&!touchContext(p,day).tired}
function jointDateFree(p,day,now){return day>now&&!touchContext(p,day).tired&&dateBookingSlots(p,day).length>0}
function nextJointDate(p,now,exclude=0){for(let d=now+1;d<=Math.min(365,now+14);d++)if(d!==exclude&&jointDateFree(p,d,now))return d;return null}
function npcChosenVenue(p){const a=npcAutonomyVoices[p],h=dateHistory(p),last=h[h.length-1]?.venue,choices=[a[0],...extraDatePlaces[p],dateLines[p][0]].filter((x,i,all)=>all.indexOf(x)===i);if(p==='임하나'&&relationshipRecall(p,initSim().day+1).kind===0&&last!=='서점')return '서점';return choices.find(x=>x!==last)||choices[0]}
function makeNpcOffer(p,day,t){const v=initSim(),soc=socialRecord(p),c=touchContext(p,day);if(platonicOnly(p))return null;if(day<7||day>=350||relationshipTier(p)<2||soc.interest<3||c.conflicted||c.tired||Object.entries(dateBook()).some(([d,b])=>Number(d)>day&&b.p===p)||t.some(m=>m.npcOffer&&!m.reply)||day-(soc.lastNpcOffer||0)<14)return null;const next=nextJointDate(p,day);if(!next)return null;const learned=relationshipRecall(p,day);const chance=p==='임하나'&&learned.kind===0?.5:p==='백지한'||p==='유지안'||p==='공재희'?.35:.22;if(Math.random()>=chance)return null;soc.lastNpcOffer=day;return {day,npcOffer:{day:next,venue:npcChosenVenue(p)},npcLine:npcAutonomyVoices[p][1]}}
function expireNpcOffers(day){for(const t of Object.values(phoneData().threads))for(const m of t)if(m.npcOffer&&!m.reply&&m.npcOffer.day<=day){m.reply=4;m.offerLabel='제안 날짜가 지났다';m.offerReply='';}}
function retryNpcOffer(p,m,messages,accepted){
 const v=initSim(),o=m.npcOffer,conflicted=touchContext(p,v.day).conflicted,occupied=!!dateBook()[o.day];
 m.reply=accepted?4:2;m.offerLabel=accepted?'좋아요. 그날 만나요.':'다른 날짜는 어때요?';
 if(conflicted){m.offerReply='미안해요. 지금은 약속보다 먼저 풀어야 할 이야기가 있는 것 같아요.';return}
 const next=nextJointDate(p,v.day,o.day);
 m.offerReply=accepted?(occupied?'앗, 그날은 이미 다른 약속이 있네요. 날짜를 다시 맞춰요.':'미안해요. 제안하고 나서 일정이 달라졌어요. 날짜를 다시 맞춰요.'):'좋아요. 다른 날로 맞춰요.';
 if(next){messages.push({day:v.day,npcOffer:{day:next,venue:o.venue},npcLine:'그러면 이 날은 어때요?'});socialRecord(p).lastNpcOffer=v.day}
 else m.offerReply+=' 지금은 맞는 날짜가 없어서 나중에 다시 정해요.';
}
function acceptNpcOffer(p,m,chosenSlot){
 const v=initSim(),o=m.npcOffer;
 if(!o||m.reply||!jointDateFree(p,o.day,v.day)||touchContext(p,v.day).conflicted)return false;
 const options=dateBookingSlots(p,o.day),slot=chosenSlot??o.slot??preferredSlot(options);
 if(!options.includes(slot))return false;
 const venue=dateVenue(p,o.venue),when=calendarDate(o.day).label+' '+dayLabels[slot];
 dateBook()[o.day]={p,slot,disclosed:false,venue,initiator:'npc'};
 o.slot=slot;m.reply=1;m.offerLabel=when+'에 만나요.';m.offerReply=npcAutonomyVoices[p][3];
 writeJournal(p+'의 제안 · '+when+' '+venue+' 약속');return true;
}
function nightNpcFree(p,day,allowDistance=false){if(npcLifeBusy(p,day,3))return false;const place=npcPlace(p,(day-1)%7,3,day),c=touchContext(p,day,allowDistance);return !['dance','police','clinic','realty','pc'].includes(place)&&!(p==='임하나'&&place==='store')&&!c.tired&&!c.conflicted}

function bookDate(p,day,venue,chosenSlot){
 if(venue==='홈데이트'&&!homeDateReady(p))return false;
 const v=initSim(),options=dateBookingSlots(p,day,true),slot=chosenSlot??preferredSlot(options);
 if(v.finished||day<=v.day||!options.includes(slot))return false;
 venue=dateVenue(p,venue);
 const when=calendarDate(day).label+' '+dayLabels[slot];
 const line=when+'에 '+(venue==='홈데이트'?'집에서 데이트할래요?':venue+' 같이 갈래요?');
 const t=phoneData().threads[p]||(phoneData().threads[p]=[]),context=touchContext(p,v.day);
 if(touchContext(p,day).tired||context.conflicted){
  const a=npcAutonomyVoices[p];
  t.push({day:v.day,booking:true,playerLine:line,npcLine:context.conflicted?touchProfiles[p].hurt[1]:a[2],reply:1});
  const next=!context.conflicted&&nextJointDate(p,v.day,day);
  if(next){t.push({day:v.day,npcOffer:{day:next,venue},npcLine:a[1]});socialRecord(p).lastNpcOffer=v.day}
  save();return true;
 }
 const leaveForDate=fixedActivity(day,slot)==='출근';
 if(!confirmDateLeave(day,slot))return false;
 const disclosed=!!leaveBook()[day]&&confirm('NPC에게 연차를 사용했다고 알려 줄까요?');
 dateBook()[day]={p,slot,disclosed,venue,leaveForDate};
 t.push({day:v.day,booking:true,playerLine:line+(disclosed?' 그날 연차 냈어요.':''),npcLine:dateConfirmLines[p][disclosed?1:0],reply:1});
 writeJournal(p+' · '+when+' '+venue+' 외출 약속');save();return true;
}
function dateControls(p,thread){
 const v=initSim();if(v.finished)return;
 const wrap=document.createElement('div');
 if(vIsDating(p)||relationshipTier(p)>=2){
  const venue=bookingSelect(wrap,'외출 장소');
  for(const name of [...new Set([dateLines[p][0],...extraDatePlaces[p],...(homeDateReady(p)?['홈데이트']:[])])])bookingOption(venue,name,name);
  const history=dateHistory(p),last=history[history.length-1];
  if(last){
   if(Array.from(venue.options).some(o=>o.value===last.venue))venue.value=last.venue;
   bookingAvailabilityNote(wrap,'지난 외출 · '+last.venue+' · '+calendarDate(last.day).label);
  }
  if(p==='공재희')bookingAvailabilityNote(wrap,'재희는 평일에도 공강이나 수업이 끝난 뒤에 만날 수 있어요.');
  const b=document.createElement('button');b.textContent='함께 외출 제안하기';
  const status=bookingAvailabilityNote(wrap,'앞으로 14일 안에 약속을 잡을 수 있는 시간이 없어요.');
  const pick=bookingPicker(wrap,v.day+1,Math.min(364,v.day+14),day=>dateBookingSlots(p,day,true),available=>{b.disabled=!available;status.hidden=available},venue.value==='홈데이트'?3:1);
  const homeHint=bookingAvailabilityNote(wrap,'연인과 밤까지 같이 있고 싶다면 저녁을 골라요. 낮에 만나도 남은 시간이 둘 다 비면 저녁까지 이어 갈 수 있어요.');
  homeHint.hidden=venue.value!=='홈데이트'||!vIsDating(p);
  venue.onchange=()=>{
   pick.refresh(venue.value==='홈데이트'?3:1);
   homeHint.hidden=venue.value!=='홈데이트'||!vIsDating(p);
  };
  b.onclick=()=>{if(!b.disabled&&bookDate(p,pick.day(),venue.value,pick.slot())){renderPhone();renderSim();syncSchedule()}};
  wrap.append(b);
 }
 for(const [key,plan] of Object.entries(dateBook())){
  const day=Number(key);
  if(day<v.day||!(plan.p===p||plan.group?.includes(p)||plan.trip?.people?.includes(p)))continue;
  const note=document.createElement('p');
  note.textContent=calendarDate(day).label+' · '+dayLabels[plan.slot]+' · '+plan.venue+' 약속 확정';wrap.append(note);
  if(plan.trip?.stage===2)continue;
  const slots=rescheduleSlots(day,plan).filter(slot=>slot!==plan.slot);
  if(!slots.length)continue;
  const details=document.createElement('details'),title=document.createElement('summary');
  title.textContent='약속 시간 변경';details.append(title);
  const sel=bookingSelect(details,'새 시간대');
  for(const slot of slots)bookingOption(sel,slot,dayLabels[slot]+(fixedActivity(day,slot)==='출근'?' (연차 필요)':''));
  const change=document.createElement('button');change.className='secondary';change.textContent='이 시간으로 변경';
  change.onclick=()=>{if(rescheduleBooking(day,plan,Number(sel.value))){renderPhone();renderSim();syncSchedule()}};
  details.append(change);wrap.append(details);
 }
 thread.append(wrap);
}
const dateHeartScenes={"공재희":["재희가 인형뽑기 기계 앞에서 손을 내밀었다.","손 줘 봐요. 같이 해요.","이렇게 가까이요?","아 왜요. 싫어요?","재희가 뽑은 인형을 당신에게 건넸다.","이거 보면 나 생각해요."],"서이준":["만원 지하철에서 서이준이 당신의 머리 위로 손잡이를 잡았다. 사람들에게 밀리지 않도록 몸으로 공간을 만들어 준다.","불편하시면 말씀하세요. 다음 역에서 자리가 날지도 모르니까요.","가까이 있으니까 조금 떨리네요.","저, 저도…… 아니, 됐어요. 잠깐만 이대로 있어요.","영화가 끝나고 나란히 걷던 서이준이 걸음을 늦췄다.","벌써 가야 돼요? …조금 더 걸어도 되잖아요."],"강도윤":["디저트 가게 앞 인파에 밀려 서로 떨어졌다. 강도윤이 사람들 사이를 헤치고 돌아와 손을 내밀었다.","찾았다. 손 잡아도 돼요? 또 놓칠까 봐요.","이번에는 놓치지 마세요.","그렇게 말씀하시면 정말 못 놓을 것 같은데요. ……괜찮아요?","강도윤은 마지막 디저트 가게 앞에서 영업시간을 확인하다 휴대전화를 넣었다.","오늘은 디저트보다 같이 있는 게 더 좋았나 봐요."],"한시우":["오락실에서 경품을 뽑으려던 한시우가 당신 쪽으로 바짝 다가와 조작법을 알려 준다. 어깨가 닿자 그가 잠시 멈췄다.","어? 너무 가까웠어요? 히히.","아뇨. 이대로 알려 주세요.","……와, 잠깐만. 저 갑자기 집중 안 되는데요?","한시우가 뽑은 작은 경품을 당신에게 건넸다.","이거 볼 때마다 저 생각하기. 약속!"],"정태오":["붐비는 버스가 급정거했다. 정태오가 당신의 팔을 받쳐 균형을 잡아 주고 곧 손을 뗐다.","괜찮습니까? 이쪽이 덜 흔들립니다.","태오 씨 옆에 있으면 든든하네요.","……그렇습니까. 다행입니다.","정태오는 돌아가는 길에 당신의 보폭에 맞춰 천천히 걸었다.","오늘은 시간이 조금 더 길었으면 했습니다."],"백지한":["전시회 인파 속에서 백지한이 당신을 발견하고 손을 내밀었다.","이렇게 놓치면 곤란한데. 손 잡아도 되죠?","지한 씨가 저를 놓치기 싫은 거예요?","……이런. 오늘은 제가 한 방 먹었네요.","백지한이 출구 앞에서 평소와 달리 잠시 말을 고른다.","다음 약속은 제가 먼저 잡아도 돼요?"],"임하나":["아쿠아리움의 어두운 통로에서 사람들이 몰려왔다. 임하나가 조심스럽게 당신의 소매를 잡았다.","...... 있잖아요. 잠깐만 이렇게 가도 될까요?","손 잡고 가도 괜찮아요.","정말요? ...... 그럼 조금만요.","임하나는 출구에 도착해서도 수조 사진을 함께 살펴보았다.","오늘은 시간이 너무 빨리 간 것 같아요."],"차유리":["전시회 포토존에서 차유리가 당신 옆에 서서 휴대전화를 들었다. 화면에 둘을 담으려니 얼굴이 가까워졌다.","같이 찍을까요? 조금 더 가까이 와도 돼요?","우리 둘이 찍은 사진 갖고 싶어요.","와, 좋아요. 저도 이 사진 오래 간직할래요.","차유리는 찍은 사진을 한참 들여다보며 웃었다.","다음엔 우리 사진 더 많이 남겨 볼까요?"],"오세린":["아쿠아리움의 좁은 통로에서 단체 관람객이 지나갔다. 오세린이 당신 쪽으로 손을 내밀었다.","으음, 사람이 많네요. 손 잡고 지나갈까요?","세린 씨랑 이렇게 있는 것도 좋네요.","후후. 저도요. 조금 천천히 가도 괜찮겠어요.","오세린이 출구 근처 벤치에 앉아 당신 옆자리를 가볍게 두드렸다.","아직 시간이 괜찮다면 조금 더 같이 있을래요?"],"유지안":["놀이공원에서 인파에 휩쓸려 서로 떨어졌다. 유지안이 당신을 찾아 뛰어왔다.","와우, 찾았다! 손 잡고 다닐까요?","지안 씨가 계속 잡아 줘요.","예쓰! 오늘은 제가 절대 안 놓칠게요.","유지안이 마지막 놀이기구를 지나쳐 당신을 바라보았다.","오늘 진짜 재밌었어요. 다음에도 둘이 와요."]};
